import{_ as s,C as r,o as n,c as l,a2 as a,b as i,w as o,a as u,E as p,a3 as d}from"./chunks/framework.BC3NdntU.js";const k=JSON.parse('{"title":"11.1 从 LLM 到 Agent:底层心智","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.md","lastUpdated":1788793004000}'),q={name:"卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.md"};function c(g,t,h,b,m,A){const e=r("Mermaid");return n(),l("div",null,[t[1]||(t[1]=a(`<h1 id="_11-1-从-llm-到-agent-底层心智" tabindex="-1">11.1 从 LLM 到 Agent:底层心智 <a class="header-anchor" href="#_11-1-从-llm-到-agent-底层心智" aria-label="Permalink to &quot;11.1 从 LLM 到 Agent:底层心智&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 难度:⭐⭐⭐ 专家 | 阅读时间:30min</p></blockquote><hr><h2 id="引言-先忘掉-ai-会思考-记住-ai-会补全" tabindex="-1">引言:先忘掉&quot;AI 会思考&quot;,记住&quot;AI 会补全&quot; <a class="header-anchor" href="#引言-先忘掉-ai-会思考-记住-ai-会补全" aria-label="Permalink to &quot;引言:先忘掉&quot;AI 会思考&quot;,记住&quot;AI 会补全&quot;&quot;">​</a></h2><p>理解 Agent、Harness、提示词工程的一切,要从一个反直觉的事实出发:<strong>大语言模型(LLM)的本质不是&quot;回答问题&quot;,而是&quot;预测下一个 token&quot;</strong>。这一章把这个底层心智立住,后面七章全部建立在此之上。</p><hr><h2 id="一、llm-的本质-自回归的-下一词预测器" tabindex="-1">一、LLM 的本质:自回归的&quot;下一词预测器&quot; <a class="header-anchor" href="#一、llm-的本质-自回归的-下一词预测器" aria-label="Permalink to &quot;一、LLM 的本质:自回归的&quot;下一词预测器&quot;&quot;">​</a></h2><p>LLM 在数学上做的事只有一件:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入一段文本(context),输出&quot;下一个 token 的概率分布&quot;,再从中采样一个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>把它反复执行(每次把刚生成的 token 追加回上下文),就得到了连贯的输出。这个过程叫<strong>自回归(autoregressive)</strong>。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(下一个词 | 之前所有词)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>为什么&quot;预测下一个词&quot;能显得&quot;智能&quot;?</strong></p><blockquote><p>预训练阶段,模型在海量文本上学&quot;<strong>给定上文,什么词最可能出现</strong>&quot;。当语料足够大,这种条件概率里<strong>被压缩进去了大量世界知识、语法、逻辑、常识</strong>——因为要预测好&quot;下个词&quot;,就必须&quot;隐式理解&quot;上文在说什么。所以&quot;补全&quot;和&quot;理解&quot;是一体两面。</p></blockquote><hr><h2 id="二、采样-为什么同样的-prompt-会有不同答案" tabindex="-1">二、采样:为什么同样的 prompt 会有不同答案 <a class="header-anchor" href="#二、采样-为什么同样的-prompt-会有不同答案" aria-label="Permalink to &quot;二、采样:为什么同样的 prompt 会有不同答案&quot;">​</a></h2><p>模型输出的是<strong>概率分布</strong>,不是唯一答案。从中&quot;采样&quot;的方式决定结果风格:</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th><th>影响</th></tr></thead><tbody><tr><td><code>temperature</code></td><td>分布&quot;陡/平&quot;</td><td>低=确定保守,高=发散创意</td></tr><tr><td><code>top_p</code></td><td>只从累积概率前 N 的候选里采</td><td>收窄候选</td></tr><tr><td><code>top_k</code></td><td>只取概率前 K 个</td><td>硬截断</td></tr></tbody></table><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># temperature=0 → 近似贪心,几乎确定;temperature=1 → 按原分布采样</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p><strong>工程启示</strong>:要稳定、可复现(代码生成、格式化输出)→ 用低温甚至 0;要多样、创意(文案、头脑风暴)→ 适当调高。这直接关联 11.6 里&quot;为什么 prompt 要约束输出格式&quot;。</p></blockquote><hr><h2 id="三、两个关键行为特性" tabindex="-1">三、两个关键行为特性 <a class="header-anchor" href="#三、两个关键行为特性" aria-label="Permalink to &quot;三、两个关键行为特性&quot;">​</a></h2><h3 id="_1-上下文学习-in-context-learning-icl" tabindex="-1">1. 上下文学习(In-Context Learning, ICL) <a class="header-anchor" href="#_1-上下文学习-in-context-learning-icl" aria-label="Permalink to &quot;1. 上下文学习(In-Context Learning, ICL)&quot;">​</a></h3><p>模型<strong>不更新权重</strong>就能学会新任务,方法是在 prompt 里<strong>给几个示例</strong>(few-shot):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把句子翻译成英文:</span></span>
<span class="line"><span>&quot;你好&quot; → &quot;Hello&quot;</span></span>
<span class="line"><span>&quot;谢谢&quot; → &quot;Thank you&quot;</span></span>
<span class="line"><span>&quot;再见&quot; →    ← 模型看示例就&quot;学会了格式与任务&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>这就是&quot;提示词即编程&quot;的根源:你不需要训练,只需要<strong>在上下文里把任务和格式讲清楚</strong>。</p></blockquote><h3 id="_2-幻觉-hallucination-与不确定性" tabindex="-1">2. 幻觉(Hallucination)与不确定性 <a class="header-anchor" href="#_2-幻觉-hallucination-与不确定性" aria-label="Permalink to &quot;2. 幻觉(Hallucination)与不确定性&quot;">​</a></h3><p>模型是&quot;用概率补全&quot;,不是&quot;查数据库&quot;。它<strong>本质上没有&quot;我不知道&quot;的强概念</strong>,所以会自信地编造事实、引用不存在的函数、给出看似合理实则错误的结果。</p><blockquote><p><strong>工程启示</strong>:一切外部事实都要<strong>靠工具/检索来锚定</strong>(11.4/11.5),而不是相信模型的&quot;记忆&quot;——这是 Agent 工程的第一铁律。</p></blockquote><hr><h2 id="四、从-聊天-到-agent-的一次心智跃迁" tabindex="-1">四、从&quot;聊天&quot;到&quot;Agent&quot;的一次心智跃迁 <a class="header-anchor" href="#四、从-聊天-到-agent-的一次心智跃迁" aria-label="Permalink to &quot;四、从&quot;聊天&quot;到&quot;Agent&quot;的一次心智跃迁&quot;">​</a></h2><p><strong>聊天模型</strong>:你一句我一句,模型只能&quot;说&quot;。</p><p><strong>Agent(智能体)</strong>:给它<strong>工具</strong>(能调用外部世界)+ <strong>循环</strong>(能持续行动)+ <strong>环境</strong>(能观察结果),它就从一个&quot;只会说话的模型&quot;变成&quot;能执行任务的系统&quot;。</p>`,32)),(n(),i(d,null,{default:o(()=>[p(e,{id:"mermaid-135",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BLLM%3Cbr%2F%3E%E9%A2%84%E6%B5%8B%E4%B8%8B%E4%B8%80%E4%B8%AA%20token%5D%20--%3E%20B%5BHarness%3Cbr%2F%3E%E8%BF%90%E8%A1%8C%E6%97%B6%E5%BE%AA%E7%8E%AF%5D%0A%20%20%20%20B%20--%3E%20C%5BPrompt%3Cbr%2F%3E%E7%9B%AE%E6%A0%87%2F%E7%BA%A6%E6%9D%9F%2F%E6%A0%BC%E5%BC%8F%5D%0A%20%20%20%20B%20--%3E%20D%5BTools%3Cbr%2F%3E%E8%83%BD%E5%8A%9B%3A%E6%9F%A5%2F%E6%90%9C%2F%E5%86%99%2F%E6%89%A7%E8%A1%8C%5D%0A%20%20%20%20B%20--%3E%20E%5BContext%3Cbr%2F%3E%E8%AE%B0%E5%BF%86%E4%B8%8E%E7%8A%B6%E6%80%81%5D%0A%20%20%20%20C%20%26%20D%20%26%20E%20--%3E%20F%5BAgent%3Cbr%2F%3E%E8%83%BD%E8%A7%82%E5%AF%9F-%E6%80%9D%E8%80%83-%E8%A1%8C%E5%8A%A8%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[u(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a(`<p><strong>一个贯穿全卷的比喻(先记住):</strong></p><blockquote><ul><li><strong>LLM</strong> = 发动机(只提供&quot;预测下一个词&quot;的动力)</li><li><strong>Prompt</strong> = 方向盘(告诉它往哪走、怎么走)</li><li><strong>Tools</strong> = 手脚(让它能碰外部世界)</li><li><strong>Context</strong> = 记忆(它记得什么、持有什么状态)</li><li><strong>Harness</strong> = 车身 + 车手(把上面这些<strong>串成一个能持续运转的循环</strong>)</li></ul></blockquote><p><strong>没有 Harness,LLM 就只是一次性的&quot;文本补全函数&quot;;有了 Harness,它才成为能千步循环、调用工具、自我纠错的 Agent。</strong> 这正是本卷叫 &quot;AI Agent <strong>Harness</strong> Engineering&quot; 的原因。</p><hr><h2 id="五、llm-的能力边界-必须清醒" tabindex="-1">五、LLM 的能力边界(必须清醒) <a class="header-anchor" href="#五、llm-的能力边界-必须清醒" aria-label="Permalink to &quot;五、LLM 的能力边界(必须清醒)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>边界</th><th>含义</th><th>化解</th></tr></thead><tbody><tr><td>上下文窗口有限</td><td>不能无限塞历史</td><td>记忆压缩/检索(11.4)</td></tr><tr><td>知识有截止</td><td>不知道&quot;最新事实&quot;</td><td>用工具检索实时数据</td></tr><tr><td>单次调用是&quot;无状态&quot;的</td><td>不记得上次对话</td><td>harness 持久化上下文</td></tr><tr><td>非确定性</td><td>同 prompt 可能不同答</td><td>低温 + 约束格式 + 重试</td></tr><tr><td>不能真正&quot;执行&quot;</td><td>只能输出文本</td><td>用 tools 把文本指向真实动作</td></tr></tbody></table><blockquote><p>一句话总结边界:<strong>LLM 是&quot;能算会写&quot;的引擎,但&quot;记得住、碰得到、做得了&quot;这些都要靠外围工程补齐。</strong></p></blockquote><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM 本质 = 自回归 next-token 预测 + 采样(temperature/top_p)</span></span>
<span class="line"><span>智能来源 = 预训练把知识/能力压缩进条件概率 → 涌现 + 上下文学习</span></span>
<span class="line"><span>关键特性:上下文学习(提示词即编程)、幻觉(概率补全≠查库)</span></span>
<span class="line"><span>Agent = LLM(引擎)+ Prompt(方向盘)+ Tools(手脚)+ Context(记忆)+ Harness(循环)</span></span>
<span class="line"><span>铁律:外部事实靠工具/检索锚定;稳定性靠低温+格式约束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="七、思考题-自测理解" tabindex="-1">七、思考题(自测理解) <a class="header-anchor" href="#七、思考题-自测理解" aria-label="Permalink to &quot;七、思考题(自测理解)&quot;">​</a></h2><p><strong>Q1:为什么说&quot;LLM 会补全&quot;和&quot;LLM 会理解&quot;是同一件事?</strong></p><p>因为要<strong>预测好下一个 token</strong>,模型必须在权重里学出对上下文的<strong>深层理解</strong>(语法、逻辑、世界知识)。&quot;补全&quot;是表面动作,&quot;理解&quot;是达成补全所必需的隐式能力,二者一体两面。</p><p><strong>Q2:如何让一个&quot;只会下一词预测&quot;的模型去执行&quot;查天气并写进文件&quot;这种任务?</strong></p><p>把任务拆成 LLM 能参与的形式:① 模型输出一个<strong>结构化的&quot;动作&quot;</strong>(如调用 <code>get_weather(city)</code>);② harness 解析这个动作,<strong>真正去执行工具</strong>;③ 把工具结果作为新的上下文喂回模型;④ 循环直到模型输出&quot;完成&quot;。关键:模型负责&quot;决策&quot;,工具与 harness 负责&quot;真的执行&quot;。</p><hr><p>📎 参考:Anthropic《Building Effective Agents》、OpenAI 文档、Attention Is All You Need 与 RLHF 相关论文</p>`,18))])}const L=s(q,[["render",c]]);export{k as __pageData,L as default};
